async(page)=>{
 const assert=(ok,msg)=>{if(!ok)throw Error(msg)},checks=[],errors=[];page.on('pageerror',e=>errors.push(e.message));
 const back=()=>page.locator('[data-page-back]').click();const nav=n=>page.locator(`[data-nav=${n}]`).first().click();const role=r=>page.locator(`[data-role=${r}]`).first().click();
 await page.goto('http://127.0.0.1:4173/prototype/#operations');await page.reload();await page.setViewportSize({width:1440,height:1000});if(await page.locator('#exit-account-preview').count())await page.locator('#exit-account-preview').click();await role('ops');
 await nav('goods');const resource=page.locator('[data-resource]').first(),id=await resource.getAttribute('data-resource');await resource.click();assert(await page.locator('.platform-detail').isVisible(),'detail absent');await back();assert(await page.locator('[data-section-tab=list]').getAttribute('class')==='active','list not restored');assert(await page.locator(`[data-resource="${id}"]`).evaluate(el=>el===document.activeElement),'focus not restored');await back();assert(page.url().endsWith('#operations'),'parent home not restored');
 checks.push('商品详情返回列表并恢复入口焦点，再返回运营中心');
 await nav('pricing');await page.locator('[data-section-tab=orders]').click();await page.locator('[data-resource]').first().click();await back();assert(await page.locator('[data-section-tab=orders]').getAttribute('class')==='active','pricing wrong tab');checks.push('订单分成详情返回原订单页签，不跳回配送服务首页');
 await role('dispatch');await nav('orders');await page.locator('#search').fill('RF-1024-001');await page.locator('[data-order="RF-1024-001"]').first().click();assert(await page.locator('.order-detail').count()>0,'order detail missing');await back();assert(await page.locator('#search').inputValue()==='RF-1024-001','search lost');assert(await page.locator('[data-backend-tab=queue]').getAttribute('class')==='active','queue lost');checks.push('订单详情返回原队列并保留搜索条件');
 await nav('dispatch');await page.locator('[data-action=busy-scenario]').click();await nav('orders');await page.locator('[data-action=next]').click();await page.locator('[data-order]').first().click();await back();assert((await page.locator('.table-foot').innerText()).includes('5–8'),'pagination lost');checks.push('分页列表进入详情再返回，保留第2页');
 await role('ops');await nav('partners');await page.locator('[data-partner]').first().click();await back();assert(await page.locator('.resource-split').getAttribute('class')==='resource-split show-list','partner list lost');
 await nav('access');await page.locator('[data-access=new]').click();await page.locator('#access-form [name=name]').fill('未保存演示');await back();assert(await page.locator('#access-form').count()===1,'unsaved editor discarded');assert((await page.locator('#toast').innerText()).includes('未保存'),'missing leave warning');await page.locator('#access-form [data-access=cancel]').first().click();assert(await page.locator('#access-form').count()===0,'form back did not return');checks.push('合作方详情返回列表；账号编辑顶部返回可用，未保存时页面返回提示先处理输入');
 await page.goto('http://127.0.0.1:4173/prototype/#goods');await page.reload();assert((await page.locator('[data-page-back]').innerText()).includes('运营中心'),'deep link fallback missing');await page.setViewportSize({width:390,height:844});assert(await page.locator('[data-page-back]').isVisible(),'mobile back hidden');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'mobile overflow');await page.screenshot({path:'E:/Dr.RouteFit/prototype/records/2026-10-24-back-navigation/mobile-back.png',fullPage:true});await back();assert(page.url().endsWith('#operations'),'fallback target wrong');
 checks.push('直接打开二级页面仍有明确父级返回；390px下可见且无整页横向溢出');assert(!errors.length,errors.join('\n'));return {status:'PASS',checks,pageErrors:errors};
}
